// Process alert trigger
const inputData = $input.first().json;
const requestData = inputData.body || inputData;

try {
  let topDeals = [];

  if (typeof requestData.topDeals === 'string') {
    topDeals = JSON.parse(requestData.topDeals);
  } else if (Array.isArray(requestData.topDeals)) {
    topDeals = requestData.topDeals;
  }

  console.log(`Processing alerts for ${topDeals.length} top deals`);

  // Filter deals by urgency
  const urgentDeals = topDeals.filter(d => d.finalScore >= 85); // S-tier
  const highPriority = topDeals.filter(d => d.finalScore >= 75 && d.finalScore < 85); // A-tier

  return [{
    json: {
      urgentDeals: urgentDeals,
      highPriority: highPriority,
      totalDeals: topDeals.length,
      timestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  console.error('Alert processing error:', error.message);
  throw error;
}

// Format SMS messages for urgent deals
const data = $input.first().json;
const urgentDeals = data.urgentDeals;

// Create individual SMS for each partner
const partners = [
  { name: 'John Partner', phone: '+1-512-555-0001', role: 'Managing Partner' },
  { name: 'Sarah Investor', phone: '+1-512-555-0002', role: 'Investment Director' },
  { name: 'Mike Analyst', phone: '+1-512-555-0003', role: 'Senior Analyst' }
];

const smsMessages = [];

partners.forEach(partner => {
  urgentDeals.forEach(deal => {
    const message = `🔥 HOT DEAL ALERT (Score: ${deal.finalScore}/100)\n\n` +
      `📍 ${deal.address}, ${deal.city}\n` +
      `💰 ${(deal.listPrice / 1000000).toFixed(2)}M | ` +
      `Cap: ${deal.propertyData.financialModel.capRate}% | ` +
      `IRR: ${deal.propertyData.financialModel.projectedIRR}%\n` +
      `🏢 ${deal.propertyType.toUpperCase()}\n\n` +
      `✨ Tier: ${deal.dealTier} - ${deal.tierDescription}\n` +
      `⚡ ${deal.action}\n\n` +
      `📊 View Details: https://propflow.app/deals/${deal.propertyId}`;

    smsMessages.push({
      to: partner.phone,
      partnerName: partner.name,
      message: message,
      dealId: deal.propertyId,
      dealScore: deal.finalScore,
      priority: 'urgent'
    });
  });
});

console.log(`Created ${smsMessages.length} urgent SMS alerts`);

return smsMessages.map(sms => ({ json: sms }));

// Simulate Twilio API call to send SMS
const sms = $input.item.json;

console.log(`[TWILIO] Sending SMS to ${sms.partnerName} (${sms.to})`);

// In production: Call Twilio API
// POST to https://api.twilio.com/2010-04-01/Accounts/{AccountSid}/Messages.json

const twilioResponse = {
  sid: `SM${Math.random().toString(36).substr(2, 32)}`,
  status: 'sent',
  to: sms.to,
  from: '+1-512-555-9999', // PropFlow Capital number
  body: sms.message,
  dateSent: new Date().toISOString(),
  price: '-0.0075',
  priceUnit: 'USD'
};

return [{
  json: {
    ...sms,
    twilioResponse: twilioResponse,
    sent: true,
    sentAt: new Date().toISOString()
  }
}];

// Format email alerts for high-priority deals
const data = $input.first().json;
const allDeals = [...(data.urgentDeals || []), ...(data.highPriority || [])];

// Create comprehensive email
const emailRecipients = [
  { name: 'Investment Team', email: 'team@propflowcapital.com' },
  { name: 'Acquisitions', email: 'acquisitions@propflowcapital.com' }
];

const emails = [];

emailRecipients.forEach(recipient => {
  // HTML email body
  const htmlBody = `
    <!DOCTYPE html>
    <html>
    <head>
      <style>
        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
        .header { background: #2c3e50; color: white; padding: 20px; text-align: center; }
        .deal-card { border: 2px solid #3498db; border-radius: 8px; padding: 20px; margin: 20px 0; }
        .deal-card.urgent { border-color: #e74c3c; background: #ffe6e6; }
        .score { font-size: 48px; font-weight: bold; color: #2c3e50; }
        .tier-S { color: #e74c3c; }
        .tier-A { color: #3498db; }
        .metrics { display: flex; justify-content: space-around; margin: 15px 0; }
        .metric { text-align: center; }
        .metric-value { font-size: 24px; font-weight: bold; color: #27ae60; }
        .action-btn { background: #e74c3c; color: white; padding: 12px 24px; text-decoration: none; border-radius: 5px; display: inline-block; margin: 10px 0; }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>🏢 PropFlow Capital - Hot Deal Alert</h1>
        <p>${new Date().toLocaleDateString()} | ${allDeals.length} High-Priority Deals</p>
      </div>

      ${allDeals.map((deal, index) => `
        <div class="deal-card ${deal.finalScore >= 85 ? 'urgent' : ''}">
          <h2>${index + 1}. ${deal.address}, ${deal.city}</h2>

          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <p><strong>Property Type:</strong> ${deal.propertyType.toUpperCase()}</p>
              <p><strong>List Price:</strong> $${(deal.listPrice / 1000000).toFixed(2)}M</p>
            </div>
            <div class="score tier-${deal.dealTier}">${deal.finalScore}</div>
          </div>

          <div class="metrics">
            <div class="metric">
              <div class="metric-value">${deal.propertyData.financialModel.capRate}%</div>
              <div>Cap Rate</div>
            </div>
            <div class="metric">
              <div class="metric-value">${deal.propertyData.financialModel.projectedIRR}%</div>
              <div>Projected IRR</div>
            </div>
            <div class="metric">
              <div class="metric-value">${deal.propertyData.financialModel.dscr}</div>
              <div>DSCR</div>
            </div>
          </div>

          <p><strong>Tier:</strong> ${deal.dealTier} - ${deal.tierDescription}</p>
          <p><strong>Recommendation:</strong> ${deal.recommendation}</p>

          <p><strong>Top Strengths:</strong></p>
          <ul>
            ${deal.topStrengths.map(s => `<li>${s}</li>`).join('')}
          </ul>

          ${deal.concerns.length > 0 ? `
            <p><strong>Concerns:</strong></p>
            <ul>
              ${deal.concerns.map(c => `<li>${c}</li>`).join('')}
            </ul>
          ` : ''}

          <a href="https://propflow.app/deals/${deal.propertyId}" class="action-btn">View Full Analysis →</a>
        </div>
      `).join('')}

      <div style="text-align: center; padding: 30px; background: #ecf0f1; margin-top: 30px;">
        <p>PropFlow Capital Deal Flow Engine</p>
        <p>Automated Property Intelligence System</p>
      </div>
    </body>
    </html>
  `;

  emails.push({
    to: recipient.email,
    recipientName: recipient.name,
    subject: `🔥 ${allDeals.filter(d => d.finalScore >= 85).length} Hot Deals + ${allDeals.filter(d => d.finalScore >= 75 && d.finalScore < 85).length} High-Priority Opportunities`,
    htmlBody: htmlBody,
    dealCount: allDeals.length,
    urgentCount: allDeals.filter(d => d.finalScore >= 85).length
  });
});

console.log(`Created ${emails.length} email alerts`);

return emails.map(email => ({ json: email }));

// Simulate SendGrid API call to send email
const email = $input.item.json;

console.log(`[SENDGRID] Sending email to ${email.recipientName} (${email.to})`);

// In production: Call SendGrid API
// POST to https://api.sendgrid.com/v3/mail/send

const sendGridResponse = {
  messageId: `<${Math.random().toString(36).substr(2, 32)}@propflowcapital.com>`,
  status: 'sent',
  to: email.to,
  from: 'alerts@propflowcapital.com',
  subject: email.subject,
  timestamp: new Date().toISOString()
};

return [{
  json: {
    ...email,
    sendGridResponse: sendGridResponse,
    sent: true,
    sentAt: new Date().toISOString()
  }
}];

// Format Slack notification
const data = $input.first().json;
const urgentDeals = data.urgentDeals || [];
const highPriority = data.highPriority || [];

const slackMessage = {
  channel: '#deal-alerts',
  text: `🚨 New Hot Deals: ${urgentDeals.length} S-Tier, ${highPriority.length} A-Tier`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '🏢 PropFlow Deal Alerts'
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${urgentDeals.length + highPriority.length}* new high-priority deals available\n*${urgentDeals.length}* S-Tier (Exceptional) | *${highPriority.length}* A-Tier (Excellent)`
      }
    },
    {
      type: 'divider'
    },
    ...urgentDeals.slice(0, 5).map(deal => ({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*🔥 ${deal.address}, ${deal.city}*\n` +
              `Score: *${deal.finalScore}/100* | Tier: *${deal.dealTier}*\n` +
              `💰 $${(deal.listPrice / 1000000).toFixed(2)}M | Cap: ${deal.propertyData.financialModel.capRate}% | IRR: ${deal.propertyData.financialModel.projectedIRR}%\n` +
              `📝 ${deal.recommendation}`
      },
      accessory: {
        type: 'button',
        text: {
          type: 'plain_text',
          text: 'View Deal'
        },
        url: `https://propflow.app/deals/${deal.propertyId}`
      }
    })),
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Updated: ${new Date().toLocaleString()}`
        }
      ]
    }
  ]
};

return [{ json: slackMessage }];

// Simulate Slack webhook
const slackMessage = $input.first().json;

console.log(`[SLACK] Posting to ${slackMessage.channel}`);

// In production: POST to Slack webhook URL

const slackResponse = {
  ok: true,
  channel: slackMessage.channel,
  ts: Date.now().toString(),
  message: slackMessage
};

return [{
  json: {
    slackResponse: slackResponse,
    sent: true,
    sentAt: new Date().toISOString()
  }
}];

// Format Zapier webhook payload
const data = $input.first().json;
const allDeals = [...(data.urgentDeals || []), ...(data.highPriority || [])];

const zapierPayload = {
  event: 'new_hot_deals',
  timestamp: new Date().toISOString(),
  totalDeals: allDeals.length,
  urgentCount: data.urgentDeals?.length || 0,
  deals: allDeals.map(deal => ({
    id: deal.propertyId,
    address: deal.address,
    city: deal.city,
    state: 'TX',
    listPrice: deal.listPrice,
    propertyType: deal.propertyType,
    score: deal.finalScore,
    tier: deal.dealTier,
    capRate: deal.propertyData.financialModel.capRate,
    irr: deal.propertyData.financialModel.projectedIRR,
    dscr: deal.propertyData.financialModel.dscr,
    recommendation: deal.recommendation,
    url: `https://propflow.app/deals/${deal.propertyId}`
  }))
};

return [{ json: zapierPayload }];

// Simulate Zapier webhook trigger
const payload = $input.first().json;

console.log(`[ZAPIER] Triggering webhook with ${payload.totalDeals} deals`);

// In production: POST to Zapier webhook URL

const zapierResponse = {
  status: 'success',
  id: `zap-${Date.now()}`,
  timestamp: new Date().toISOString()
};

return [{
  json: {
    zapierResponse: zapierResponse,
    triggered: true,
    triggeredAt: new Date().toISOString()
  }
}];

// Log all alert activity
const allAlerts = $input.all();

const summary = {
  timestamp: new Date().toISOString(),
  workflow: 'Alert Distribution System',
  smsCount: allAlerts.filter(a => a.json.twilioResponse).length,
  emailCount: allAlerts.filter(a => a.json.sendGridResponse).length,
  slackSent: allAlerts.some(a => a.json.slackResponse),
  zapierTriggered: allAlerts.some(a => a.json.zapierResponse),
  totalAlerts: allAlerts.length,
  success: true
};

console.log('Alert distribution complete:', JSON.stringify(summary, null, 2));

return [{ json: summary }];
